import pandas as pd

def clean(df):
    # Standardize Region labels (case‑fold and map known misspellings)
    region_map = {"north": "North", "nort": "North", "east": "East", "suoth": "South", "wst": "West"}
    df['Region'] = df['Region'].str.strip().str.title()
    df['Region'] = df['Region'].map(region_map).fillna(df['Region'])
    # Convert Price from text (possible $ and commas) to numeric
    def parse_price(p):
        if isinstance(p, str):
            p = p.replace('$', '').replace(',', '')
        return float(p)
    df['Price'] = df['Price'].astype(str).apply(parse_price)
    # Ensure Quantity is integer (already numeric per profile, but keep safe)
    df['Quantity'] = df['Quantity'].astype(int)
    return df

def answer(df):
    # Sum Quantity per Region
    result = df.groupby('Region')['Quantity'].sum().to_dict()
    # Remove any missing group keys (should not be any after cleaning)
    result = {k: v for k, v in result.items() if pd.notna(k)}
    return result
